// =============================================================================
// loader.js: load a saved arXiv paper, clean it, detect sections, and turn
// words into footholds for the spider.
//
//   listPapers()            -> [{ id, file, title }]
//   loadPaper(file, mount)  -> Paper object (see bottom of file)
//
// Papers were downloaded by fetch_paper.py into papers/{file}.html + .json.
// arXiv's HTML is generated by LaTeXML, so most selectors below use its
// "ltx_" class names, with generic fallbacks for anything else.
// =============================================================================

// Elements whose text should NEVER be split into word spans.
// MathML renders natively and breaks if you put spans inside it.
const SKIP_TAGS = new Set(['MATH', 'CODE', 'PRE', 'SCRIPT', 'STYLE', 'SVG', 'IMG', 'TEXTAREA', 'BUTTON', 'SELECT']);

// "Blocks" are the chunks we lazily word-wrap as they approach the viewport.
const WRAP_BLOCK_SEL = 'p, li, figcaption, td, th, h1, h2, h3, h4, h5, h6, dt, dd, .ltx_bibblock, .paper-head div';

// Paragraph-level blocks used for section text (what we send to Claude).
const TEXT_BLOCK_SEL = 'p, figcaption, li.ltx_bibitem, table.ltx_equation, table.ltx_tabular, .ltx_listing';

// Section headings, in priority order. h5 (\paragraph{...}) is too granular.
const HEADING_SEL = 'h2, h3, h4, h6.ltx_title_abstract';

export async function listPapers() {
  // serve.py builds the list live; papers/index.json is the static fallback.
  for (const url of ['/api/papers', 'papers/index.json']) {
    try {
      const res = await fetch(url);
      if (res.ok) return await res.json();
    } catch { /* try next */ }
  }
  return [];
}

export async function loadPaper(file, mount) {
  const [htmlRes, metaRes] = await Promise.all([
    fetch(`papers/${file}.html`),
    fetch(`papers/${file}.json`),
  ]);
  if (!htmlRes.ok) throw new Error(`papers/${file}.html not found. Run: python fetch_paper.py ${file}`);
  const meta = metaRes.ok ? await metaRes.json() : { id: file, title: file, authors: [] };

  // Parse in an inert document: nothing executes, no images load yet.
  const doc = new DOMParser().parseFromString(await htmlRes.text(), 'text/html');
  const article = doc.querySelector('article.ltx_document') ||
                  doc.querySelector('.ltx_page_content') ||
                  doc.querySelector('main') || doc.body;

  cleanArticle(article);

  // --- Build the visible sheet: our minimal header + the article -----------
  mount.textContent = '';
  const head = document.createElement('header');
  head.className = 'paper-head';
  const h1 = document.createElement('h1');
  h1.textContent = meta.title;
  const authors = document.createElement('div');
  authors.className = 'authors';
  authors.textContent = (meta.authors || []).join(', ');
  const idLine = document.createElement('div');
  idLine.className = 'arxiv-id';
  idLine.innerHTML = `arXiv:<a href="https://arxiv.org/abs/${meta.id}" target="_blank" rel="noopener">${meta.id}</a>` +
    (meta.published ? ` · ${meta.published}` : '');
  head.append(h1, authors, idLine);

  const body = document.importNode(article, true);
  body.classList.add('paper-body');
  mount.append(head, body);

  // Lazy-load figures so a long paper doesn't fetch 40 images up front.
  for (const img of body.querySelectorAll('img')) img.loading = 'lazy';

  const sections = detectSections(mount, head, body, meta);
  const wrapper = createLazyWrapper(mount);

  return {
    meta,
    root: mount,
    body,
    head,
    sections,
    wrapper,
    sectionIndexOf: (el) => sectionIndexOf(sections, el),
    findPhrase: (phrase, hintIndex) => findPhrase(sections, wrapper, phrase, hintIndex),
    blockText,
    destroy: () => wrapper.disconnect(),
  };
}

// -----------------------------------------------------------------------------
// Cleaning: strip site chrome and anything interactive we don't want.
// -----------------------------------------------------------------------------
function cleanArticle(article) {
  const junk = [
    'script', 'style', 'link', 'noscript', 'iframe', 'nav', 'button',
    '.ltx_page_navbar', '.ltx_page_footer', '.ltx_page_header', '.ltx_page_logo',
    '.ar5iv-footer', '.ar5iv-toc', '#header', '.html-header-message', '.package-alerts',
    '.ltx_role_footnote .ltx_note_outer', // footnote popups; marks still render
  ];
  for (const el of article.querySelectorAll(junk.join(','))) el.remove();
  // Inline styles from the source sometimes fight the paper theme (fixed widths, etc.)
  for (const el of article.querySelectorAll('[style]')) {
    if (el.tagName !== 'IMG' && !el.closest('math')) el.removeAttribute('style');
  }
  // Links inside the paper open in a new tab, except in-paper anchors (#S3, #bib.bib12).
  for (const a of article.querySelectorAll('a[href]')) {
    if (!a.getAttribute('href').startsWith('#')) {
      a.target = '_blank';
      a.rel = 'noopener';
    }
  }
}

// -----------------------------------------------------------------------------
// Section detection
//
// A section runs from its heading up to (not including) the next heading.
// We record:
//   label     "3.2 Attention" (normalized heading text)
//   heading   the heading element (for the purple bar + position lookups)
//   range     a DOM Range covering the section
//   blocks    paragraph-level elements inside it (for building the text)
//   text      the section's plain text, math replaced by its LaTeX source
//   isRefs    true for References/Bibliography (the camera stops here)
// -----------------------------------------------------------------------------
function detectSections(mount, head, body, meta) {
  const headings = [...body.querySelectorAll(HEADING_SEL)].filter((h) =>
    !h.closest('figure, table, .ltx_authors, .ltx_title_document') &&
    !h.classList.contains('ltx_title_document') &&
    h.textContent.trim().length > 0
  );

  const sections = [{
    label: 'Title',
    heading: head.querySelector('h1'),
    level: 0,
    isAbstract: false,
    isRefs: false,
  }];
  for (const h of headings) {
    const label = h.textContent.replace(/\s+/g, ' ').trim();
    sections.push({
      label,
      heading: h,
      level: h.classList.contains('ltx_title_abstract') ? 1 : Number(h.tagName[1]) - 1,
      isAbstract: /^abstract$/i.test(label) || h.classList.contains('ltx_title_abstract'),
      isRefs: /^(\d+\s*)?(references|bibliography)$/i.test(label) ||
              h.classList.contains('ltx_title_bibliography'),
    });
  }

  // DOM ranges, from each heading to the next one.
  for (let i = 0; i < sections.length; i++) {
    const s = sections[i];
    const range = document.createRange();
    range.setStartBefore(s.heading);
    const next = sections[i + 1];
    if (next) range.setEndBefore(next.heading);
    else range.setEndAfter(body.lastChild || body);
    s.range = range;
    s.blocks = [];
    s.index = i;
  }

  // Assign each text block to its section by walking both lists in document order.
  const blocks = [...mount.querySelectorAll(TEXT_BLOCK_SEL)].filter(
    (b) => !b.parentElement.closest(TEXT_BLOCK_SEL) // drop nested duplicates
  );
  let si = 0;
  for (const b of blocks) {
    while (si + 1 < sections.length &&
           (sections[si + 1].heading.compareDocumentPosition(b) & Node.DOCUMENT_POSITION_FOLLOWING)) {
      si++;
    }
    sections[si].blocks.push(b);
  }

  for (const s of sections) {
    s.text = s.blocks.map(blockText).filter(Boolean).join('\n\n');
  }
  // The title "section" explains nothing on its own; give it the abstract from
  // the arXiv API in case the HTML lacks an abstract block.
  if (!sections[0].text) sections[0].text = meta.abstract || '';
  return sections;
}

// Plain text of a block, with <math> replaced by its LaTeX source (alttext),
// since MathML's textContent is unreadable soup.
export function blockText(el) {
  let out = '';
  const walk = (node) => {
    if (node.nodeType === Node.TEXT_NODE) { out += node.nodeValue.replace(/\s+/g, ' '); return; }
    if (node.nodeType !== Node.ELEMENT_NODE) return;
    if (node.tagName === 'MATH' || node.localName === 'math') {
      const tex = node.getAttribute('alttext');
      out += tex ? ` $${tex}$ ` : node.textContent;
      return;
    }
    if (node.tagName === 'IMG') return;
    for (const c of node.childNodes) walk(c);
    // Keep table structure readable: "cell | cell" per row.
    if (node.tagName === 'TD' || node.tagName === 'TH') out += ' | ';
    else if (node.tagName === 'TR') out += '\n';
  };
  walk(el);
  return out.replace(/[ \t\r\f\v]+/g, ' ').replace(/ *\n */g, '\n').trim();
}

function sectionIndexOf(sections, el) {
  for (let i = sections.length - 1; i >= 0; i--) {
    const h = sections[i].heading;
    if (h === el || h.contains(el) ||
        (h.compareDocumentPosition(el) & Node.DOCUMENT_POSITION_FOLLOWING)) return i;
  }
  return 0;
}

// -----------------------------------------------------------------------------
// Word wrapping: every text node becomes <span class="w">word</span> footholds.
//
// Papers are long (thousands of paragraphs), so we only wrap blocks near the
// viewport. An IntersectionObserver queues blocks; the crawler's commit()
// phase calls flush() once per frame to do the DOM writes, a few blocks at a time.
// -----------------------------------------------------------------------------
function createLazyWrapper(mount) {
  const queue = new Set();
  const io = new IntersectionObserver((entries) => {
    for (const e of entries) {
      if (e.isIntersecting) {
        queue.add(e.target);
        io.unobserve(e.target);
      }
    }
  }, { root: document.getElementById('scroller'), rootMargin: '800px 0px' });

  for (const block of mount.querySelectorAll(WRAP_BLOCK_SEL)) {
    if (!block.closest('math')) io.observe(block);
  }

  return {
    // Wrap up to `budget` queued blocks. Called from the crawler's commit().
    flush(budget = 12) {
      for (const block of queue) {
        if (budget-- <= 0) break;
        queue.delete(block);
        wrapBlock(block);
      }
    },
    wrapNow: wrapBlock,
    disconnect: () => io.disconnect(),
  };
}

function wrapBlock(block) {
  if (block.dataset.wrapped) return;
  block.dataset.wrapped = '1';

  // Collect first, then mutate: modifying the tree mid-walk confuses TreeWalker.
  const walker = document.createTreeWalker(block, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      if (!node.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
      for (let p = node.parentElement; p && p !== block.parentElement; p = p.parentElement) {
        if (SKIP_TAGS.has(p.tagName.toUpperCase()) || p.namespaceURI === 'http://www.w3.org/1998/Math/MathML') {
          return NodeFilter.FILTER_REJECT;
        }
        if (p.classList.contains('w')) return NodeFilter.FILTER_REJECT; // already wrapped
      }
      return NodeFilter.FILTER_ACCEPT;
    },
  });
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);

  for (const node of nodes) {
    const frag = document.createDocumentFragment();
    // Split on whitespace but keep it, so spacing and line-breaking are unchanged.
    for (const part of node.nodeValue.split(/(\s+)/)) {
      if (!part) continue;
      if (/^\s+$/.test(part)) {
        frag.append(part);
      } else {
        const span = document.createElement('span');
        span.className = 'w';
        span.textContent = part;
        frag.append(span);
      }
    }
    node.replaceWith(frag);
  }
}

// -----------------------------------------------------------------------------
// findPhrase: locate the exact text Claude returned on its "KEY:" line.
// Returns { spans: [.w elements], block } or null. Wraps the block if needed
// (callers run this inside the crawler's commit phase, where writes are allowed).
// -----------------------------------------------------------------------------
const norm = (s) => s.toLowerCase().replace(/[‘’]/g, "'").replace(/[“”]/g, '"')
  .replace(/[–—]/g, '-').replace(/\s+/g, ' ').trim();

function findPhrase(sections, wrapper, phrase, hintIndex = -1) {
  phrase = norm(phrase.replace(/^["'`*]+|["'`*.]+$/g, ''));
  if (!phrase) return null;

  // Search only the section Claude was explaining, so a KEY never drags the
  // spider across the paper. With no hint, search everything.
  const order = sections[hintIndex] ? [sections[hintIndex]] : sections;

  const attempts = [phrase];
  // Fallbacks: the most "number-like" token, then the longest word.
  const num = phrase.match(/[+\-−]?\d[\d.,]*\s*(%|bleu|x|×)?/i);
  if (num) attempts.push(norm(num[0]));
  const longest = phrase.split(' ').sort((a, b) => b.length - a.length)[0];
  if (longest && longest.length > 4) attempts.push(longest);

  // Exact phrase first, then the fallbacks.
  for (const s of order) {
    for (const needle of attempts) {
      for (const block of s.blocks) {
        const plain = norm(block.textContent);
        const withTex = norm(blockText(block));
        if (!plain.includes(needle) && !withTex.includes(needle)) continue;
        // Make sure it has footholds, then find the run of words matching the needle.
        wrapBlockDeep(block, wrapper);
        const hit = matchSpans([...block.querySelectorAll('.w')], needle);
        if (hit.length) return { spans: hit, block, section: s.index };
        // Not in the words? It may be inside an equation: point at the <math> itself.
        const squash = (t) => norm(t).replace(/[\s{}\\]/g, '');
        for (const m of block.querySelectorAll('math')) {
          if (squash(m.getAttribute('alttext') || '').includes(squash(needle))) {
            return { spans: [m], block, section: s.index };
          }
        }
      }
    }
  }
  return null;
}

function wrapBlockDeep(block, wrapper) {
  wrapper.wrapNow(block);
  for (const inner of block.querySelectorAll(WRAP_BLOCK_SEL)) wrapper.wrapNow(inner);
}

// Join span texts with spaces, find the needle, and return the spans it covers.
function matchSpans(spans, needle) {
  let joined = '';
  const starts = [];
  for (const sp of spans) {
    starts.push(joined.length);
    joined += norm(sp.textContent) + ' ';
  }
  // The match must start at a word and end at a word boundary ("8" must not match inside "28.4").
  const startSet = new Set(starts);
  let at = -1;
  for (let i = joined.indexOf(needle); i >= 0; i = joined.indexOf(needle, i + 1)) {
    const after = joined[i + needle.length] || ' ';
    if (startSet.has(i) && /[\s.,;:)\]%]/.test(after)) { at = i; break; }
  }
  if (at < 0) return [];
  const end = at + needle.length;
  return spans.filter((_, i) => {
    const s = starts[i], e = s + spans[i].textContent.length;
    return e > at && s < end;
  }).slice(0, 8);
}
